package com.example.partnerintegrationmock.application;
import com.example.partnerintegrationmock.integration.AppointmentCallbackClient; import com.example.partnerintegrationmock.model.MockBooking; import org.springframework.stereotype.Service; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
@Service public class MockBookingService {
 private final Map<UUID,MockBooking> byAppointment=new ConcurrentHashMap<>(); private final Map<String,MockBooking> byReference=new ConcurrentHashMap<>(); private final AppointmentCallbackClient callbacks;
 public MockBookingService(AppointmentCallbackClient c){callbacks=c;}
 public synchronized MockBooking submit(UUID id,String vehicle,String dealer,String name,String slot,String type){var existing=byAppointment.get(id); if(existing!=null){if(existing.same(id,vehicle,dealer,name,slot,type)) return existing; throw new Conflict("Conflicting booking submission for appointmentId");} var ref="PARTNER-REQUEST-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(); var booking=new MockBooking(id,vehicle,dealer,name,slot,type,ref);byAppointment.put(id,booking);byReference.put(ref,booking);return booking;}
 public Collection<MockBooking> list(){return List.copyOf(byReference.values());} public MockBooking get(String ref){var b=byReference.get(ref);if(b==null)throw new Missing("Mock booking not found: "+ref);return b;}
 public synchronized MockBooking confirm(String ref){var b=get(ref);if(b.confirmCallbackState==MockBooking.Delivery.DELIVERED)return b;if(b.state!=MockBooking.State.RECEIVED)throw new Conflict("Booking cannot be confirmed from "+b.state);if(b.externalDmsReference==null)b.externalDmsReference="DMS-BOOKING-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();try{callbacks.confirm(b.appointmentId,b.externalDmsReference);b.confirmCallbackState=MockBooking.Delivery.DELIVERED;b.state=MockBooking.State.CONFIRMED;b.lastCallbackError=null;}catch(Exception e){b.confirmCallbackState=MockBooking.Delivery.FAILED;b.lastCallbackError="Appointment confirmation callback failed";}return b;}
 public synchronized MockBooking complete(String ref){var b=get(ref);if(b.completeCallbackState==MockBooking.Delivery.DELIVERED)return b;if(b.state!=MockBooking.State.CONFIRMED)throw new Conflict("Booking must be confirmed before completion");try{callbacks.complete(b.appointmentId,b.externalDmsReference);b.completeCallbackState=MockBooking.Delivery.DELIVERED;b.state=MockBooking.State.COMPLETED;b.lastCallbackError=null;}catch(Exception e){b.completeCallbackState=MockBooking.Delivery.FAILED;b.lastCallbackError="Appointment completion callback failed";}return b;}
 public static class Missing extends RuntimeException{public Missing(String m){super(m);}} public static class Conflict extends RuntimeException{public Conflict(String m){super(m);}}
}
